package com.andye.warmod.block.entity;

import com.andye.warmod.radar.display.RadarDisplayConstants; import com.andye.warmod.radar.display.RadarDisplayLink; import com.andye.warmod.radar.display.network.RadarDisplayNetworking; import java.util.Objects; import java.util.UUID; import net.minecraft.core.BlockPos; import net.minecraft.core.UUIDUtil; import net.minecraft.network.protocol.Packet; import net.minecraft.network.protocol.game.ClientGamePacketListener; import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.level.storage.ValueInput; import net.minecraft.world.level.storage.ValueOutput; import org.jspecify.annotations.Nullable;
public final class RadarDisplayPanelBlockEntity extends BlockEntity { private @Nullable UUID displayId; private BlockPos controller; private int width,height,tileX,tileY; private boolean valid; private @Nullable RadarDisplayLink link; private long lastBroadcastGameTime=-1L; public RadarDisplayPanelBlockEntity(BlockPos position,BlockState state){super(ModBlockEntities.RADAR_DISPLAY_PANEL,position,state);controller=position;} public static void serverTick(Level level,BlockPos position,BlockState state,RadarDisplayPanelBlockEntity display){if(!(level instanceof ServerLevel server)||!display.controllerPanel()||display.displayId==null)return;long now=server.getGameTime();if(display.lastBroadcastGameTime>=0L&&now-display.lastBroadcastGameTime<RadarDisplayConstants.BROADCAST_INTERVAL_TICKS)return;display.lastBroadcastGameTime=now;RadarDisplayNetworking.sendState(display);} public void configure(@Nullable UUID displayId,BlockPos controller,int width,int height,int tileX,int tileY,boolean valid,@Nullable RadarDisplayLink commonLink){boolean changed=!Objects.equals(this.displayId,displayId)||!this.controller.equals(controller)||this.width!=width||this.height!=height||this.tileX!=tileX||this.tileY!=tileY||this.valid!=valid||!Objects.equals(this.link,commonLink);this.displayId=displayId;this.controller=controller.immutable();this.width=width;this.height=height;this.tileX=tileX;this.tileY=tileY;this.valid=valid;this.link=commonLink;if(changed)sync();} public void link(RadarDisplayLink value){if(Objects.equals(link,value))return;link=value;sync();if(controllerPanel())RadarDisplayNetworking.sendState(this);} public void clearLink(){if(link==null)return;link=null;sync();if(controllerPanel())RadarDisplayNetworking.sendState(this);} public @Nullable RadarDisplayLink link(){return link;} public @Nullable UUID displayId(){return displayId;} public BlockPos controller(){return controller;} public int width(){return width;} public int height(){return height;} public int tileX(){return tileX;} public int tileY(){return tileY;} public double horizontalRadius(){return valid?RadarDisplayConstants.horizontalRadius(width):0.0;} public double verticalRadius(){return valid?RadarDisplayConstants.verticalRadius(height):0.0;} public boolean valid(){return valid;} public boolean controllerPanel(){return valid&&worldPosition.equals(controller);}
@Override public void setRemoved(){if(level instanceof ServerLevel server&&controllerPanel()&&displayId!=null)RadarDisplayNetworking.clear(server,controller,displayId);super.setRemoved();} @Override protected void saveAdditional(ValueOutput output){super.saveAdditional(output);output.storeNullable("display_id",UUIDUtil.CODEC,displayId);output.store("controller",BlockPos.CODEC,controller);output.putInt("width",width);output.putInt("height",height);output.putInt("tile_x",tileX);output.putInt("tile_y",tileY);output.putBoolean("valid",valid);if(link!=null)output.store("link",RadarDisplayLink.CODEC,link);} @Override protected void loadAdditional(ValueInput input){super.loadAdditional(input);displayId=input.read("display_id",UUIDUtil.CODEC).orElse(null);controller=input.read("controller",BlockPos.CODEC).orElse(worldPosition);int legacy=input.getIntOr("size",0);width=input.getIntOr("width",legacy);height=input.getIntOr("height",legacy);tileX=input.getIntOr("tile_x",0);tileY=input.getIntOr("tile_y",0);valid=input.getBooleanOr("valid",false);link=input.read("link",RadarDisplayLink.CODEC).orElse(null);} private void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);} @Override public @Nullable Packet<ClientGamePacketListener> getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public net.minecraft.nbt.CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider registries){return saveCustomOnly(registries);} }